#!/usr/bin/env python3
"""Prepare the person pictures (generated by the user with GPT from 图片prompt.md; 1024×1536, transparent) for the film.
Inputs: a folder with 1-base, 2-lipstick, 3-contour, 4-makeup, 5-mask, 6-hand (.webp or .png).
Writes assets/people/*.webp:
  base, makeup, contour, mask, lipstick, hand  — defringed (the half-transparent edge pixels take the colour of the opaque
                                                  pixels next to them, so no yellow halo on the dark scenes)
  lipstick-hand   — only the hand and the lipstick (what differs from 'makeup' in the lower right), to move it away
  mask-layer      — only the mask and its ear loop (what differs from 'makeup'), to put it on
  screen-mask     — white where the phone's screen is (the dark grey area), for drawing the lock / keypad on it
and prints the screen's bounding box."""
import sys, pathlib
import numpy as np
from PIL import Image, ImageFilter

ROOT = pathlib.Path(__file__).resolve().parent.parent
SRC = pathlib.Path(sys.argv[1])
OUT = ROOT / "assets/people"; OUT.mkdir(parents=True, exist_ok=True)
names = {"base": "1-base", "lipstick": "2-lipstick", "contour": "3-contour", "makeup": "4-makeup", "mask": "5-mask", "hand": "6-hand"}

def load(n):
    for ext in (".png", ".webp"):
        p = SRC / (names[n] + ext)
        if p.exists(): return np.asarray(Image.open(p).convert("RGBA")).astype(np.float32)
    raise FileNotFoundError(names[n])

def defringe(a):
    rgb, al = a[:, :, :3], a[:, :, 3:4] / 255.0
    solid = (al > 0.98).astype(np.float32)
    acc = rgb * solid; w = solid.copy()
    for r in (2, 4, 8):                                   # spread the opaque colours outwards
        k = Image.fromarray((w[:, :, 0] * 255).astype(np.uint8)).filter(ImageFilter.BoxBlur(r))
        kw = np.asarray(k).astype(np.float32)[:, :, None] / 255.0
        ka = np.stack([np.asarray(Image.fromarray(np.clip(acc[:, :, c], 0, 255).astype(np.uint8)).filter(ImageFilter.BoxBlur(r))).astype(np.float32) for c in range(3)], 2)
        fill = (w == 0) & (kw > 0.01)
        acc = np.where(fill, ka / np.maximum(kw, 1e-3) * kw, acc); w = np.where(fill, kw, w)
    spread = acc / np.maximum(w, 1e-3)
    out = a.copy(); edge = (al[:, :, 0] < 0.98)
    out[:, :, :3][edge] = spread[edge]
    out[:, :, 3] = np.where(al[:, :, 0] < 0.06, 0, a[:, :, 3])   # drop the faintest specks
    return out

def save(a, n):
    Image.fromarray(np.clip(a, 0, 255).astype(np.uint8), "RGBA").save(OUT / f"{n}.webp", quality=92, method=6)

imgs = {n: defringe(load(n)) for n in names}
for n, a in imgs.items(): save(a, n)

def layer(a, ref, region, thr=36, grow=6):
    d = np.abs(a[:, :, :3] - ref[:, :, :3]).sum(2) + np.abs(a[:, :, 3] - ref[:, :, 3]) * 2
    m = (d > thr) & region & (a[:, :, 3] > 20)
    mi = Image.fromarray((m * 255).astype(np.uint8)).filter(ImageFilter.MaxFilter(5)).filter(ImageFilter.MinFilter(5))
    mi = mi.filter(ImageFilter.MaxFilter(2 * (grow // 2) + 1)).filter(ImageFilter.GaussianBlur(2))
    k = np.asarray(mi).astype(np.float32) / 255.0
    out = a.copy(); out[:, :, 3] = a[:, :, 3] * k
    return out

H, W = 1536, 1024
yy, xx = np.mgrid[0:H, 0:W]
mk = imgs["makeup"]
# the hand and the lipstick: the lower right, below the lips
lp = imgs["lipstick"]; r, g, b = lp[:, :, 0], lp[:, :, 1], lp[:, :, 2]
skin = (r > 200) & (g > 160) & (b > 130) & (r - b > 40); shirt = (r > 215) & (g > 205) & (b > 195) & (r - b < 30)
handish = (((yy > 960) & (xx > 748)) | ((yy > 872) & (xx > 790) & ~skin)) & ~shirt   # the hand and the lipstick only
save(layer(lp, mk, handish, thr=30), "lipstick-hand")
# the mask: the lower face and the loops round the ear
ms = imgs["mask"]; r, g, b = ms[:, :, 0], ms[:, :, 1], ms[:, :, 2]
blue = (b - r > 10) & (b > 165) & (yy > 560) & (yy < 1080) & (xx > 560)          # the mask itself
loop = (r > 228) & (g > 228) & (b > 228) & (yy > 560) & (yy < 1000) & (xx > 400) & (xx < 640)   # the ear loops
save(layer(ms, mk, blue | loop, thr=0, grow=6), "mask-layer")
# the phone's screen: the big dark-grey area (flood from the middle of the phone)
h = imgs["hand"]; rgb = h[:, :, :3]
dark = (np.abs(rgb - np.array([50, 50, 56])).sum(2) < 40) & (h[:, :, 3] > 200)
from collections import deque
seen = np.zeros_like(dark); q = deque([(700, 512)]); seen[700, 512] = True
while q:
    y, x = q.popleft()
    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        ny, nx = y + dy, x + dx
        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and dark[ny, nx]: seen[ny, nx] = True; q.append((ny, nx))
scr = Image.fromarray((seen * 255).astype(np.uint8)).filter(ImageFilter.MaxFilter(5)).filter(ImageFilter.MinFilter(3))
m8 = np.asarray(scr); Image.fromarray(np.dstack([np.full_like(m8, 255)] * 3 + [m8]), "RGBA").save(OUT / "screen-mask.png")   # alpha = the screen (canvas destination-in reads alpha)
ys, xs = np.where(np.asarray(scr) > 128)
print("screen bbox", xs.min(), ys.min(), xs.max(), ys.max())
for f in sorted(OUT.iterdir()): print(f.name, f.stat().st_size // 1024, "KB")
